locals {
  # Mandatory cost-allocation tags enforced by policy-as-code (see Conftest)
  common_tags = {
    team        = "data-platform"
    env         = "prod"
    cost_center = "de-1042"
    managed_by  = "terraform"
  }
}

# Spot node group that autoscales from 0 for retryable batch/CI workloads
resource "aws_eks_node_group" "spot_batch" {
  cluster_name    = var.cluster_name
  node_group_name = "spot-batch"
  node_role_arn   = var.node_role_arn
  subnet_ids      = var.subnet_ids

  capacity_type  = "SPOT"
  instance_types = ["m6i.large", "m6a.large", "m5.large"] # diversify to reduce interruption

  scaling_config {
    min_size     = 0   # scale to zero when idle
    desired_size = 0
    max_size     = 20
  }

  labels = { workload = "batch", lifecycle = "spot" }
  tags   = local.common_tags
}

# Data bucket: tier cold data down, then expire it to control storage cost
resource "aws_s3_bucket" "data" {
  bucket = "acme-data-platform-prod"
  tags   = local.common_tags
}

resource "aws_s3_bucket_lifecycle_configuration" "data" {
  bucket = aws_s3_bucket.data.id
  rule {
    id     = "tier-and-expire"
    status = "Enabled"
    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }
    transition {
      days          = 90
      storage_class = "GLACIER"
    }
    expiration {
      days = 365
    }
  }
}
